# GENESIS Job A phase-diagram sweep on Kaggle CPU (all cores). Stops cleanly at 11.3h; cells.jsonl is appended per finished cell.
import io,base64,tarfile,os,subprocess,sys
os.chdir("/kaggle/working"); tarfile.open(fileobj=io.BytesIO(base64.b64decode("")),mode="r:gz").extractall("/kaggle/working/code")
OUT="/kaggle/working/sweep"; os.makedirs(OUT,exist_ok=True)
r=subprocess.run([sys.executable,"-u","-m","genesis.colab_jobs","sweep","--drive",OUT,"--hours","11.3"],cwd="/kaggle/working/code")
subprocess.run([sys.executable,"-m","genesis.colab_jobs","render","--drive",OUT],cwd="/kaggle/working/code")
import shutil; shutil.rmtree(os.path.join(OUT,"tmp"),ignore_errors=True); shutil.rmtree("/kaggle/working/code",ignore_errors=True)
print("rc",r.returncode)
